import React from 'react';
import { SafeAreaView, StyleSheet, Text, View } from 'react-native';
import { Colors } from '@constants/colors';

const mapboxToken = process.env.EXPO_PUBLIC_MAPBOX_TOKEN ?? '';

const leafletMapHtml = `
<!DOCTYPE html>
<html>
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
    <style>
      html, body, #map {
        margin: 0;
        width: 100%;
        height: 100%;
        background: #e5efe8;
      }
      body {
        font-family: Arial, sans-serif;
      }
      .leaflet-container {
        background: #e5efe8;
      }
      .leaflet-popup-content-wrapper,
      .leaflet-popup-tip {
        background: #ffffff;
      }
    </style>
  </head>
  <body>
    <div id="map"></div>
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <script>
      const biñan = [14.3036, 121.0781];

      const map = L.map('map', {
        zoomControl: true,
        attributionControl: true
      }).setView(biñan, 13);

      L.tileLayer('https://api.mapbox.com/styles/v1/mapbox/streets-v12/tiles/{z}/{x}/{y}?access_token=${mapboxToken}&tileSize=512', {
        attribution: '&copy; Mapbox &copy; OpenStreetMap contributors',
        maxZoom: 19
      }).addTo(map);

      const marker = L.marker(biñan).addTo(map);
      marker.bindPopup('Biñan City, Laguna');

      const bounds = [[14.2500, 121.0200], [14.3600, 121.1400]];
      map.fitBounds(bounds);
    </script>
  </body>
</html>
`;

export default function MapScreen() {
  return (
    <SafeAreaView style={styles.safeArea}>
      <View style={styles.header}>
        <Text style={styles.headerTitle}>MAP</Text>
        <Text style={styles.headerSubtitle}>Biñan City, Laguna</Text>
      </View>

      <View style={styles.webMap}>
        <iframe
          title="Binan City Map"
          srcDoc={leafletMapHtml}
          style={styles.mapFrame}
        />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safeArea: { flex: 1, backgroundColor: Colors.white },
  header: { backgroundColor: '#218B25', paddingHorizontal: 18, paddingTop: 18, paddingBottom: 12 },
  headerTitle: { color: Colors.white, fontSize: 28, fontWeight: '800' },
  headerSubtitle: { color: '#DFF1DF', fontSize: 12, marginTop: 2 },
  webMap: { flex: 1, margin: 14, borderWidth: 1, borderColor: '#218B25', borderRadius: 8, overflow: 'hidden', backgroundColor: '#EAF2EF' },
  mapFrame: { width: '100%', height: '100%', borderWidth: 0 },
});
